import{_ as e,o as t,c as i,ag as o}from"./chunks/framework.By9v0nLp.js";const s="/wiki/nostalgicdialog/banner.gif",u=JSON.parse('{"title":"Nostalgic Dialog Wiki","description":"","frontmatter":{"title":"Nostalgic Dialog Wiki"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),n={name:"index.md"};function r(l,a,c,d,h,g){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="nostalgic-dialog" tabindex="-1">Nostalgic Dialog <a class="header-anchor" href="#nostalgic-dialog" aria-label="Permalink to &quot;Nostalgic Dialog&quot;">​</a></h1><img src="'+s+'" alt="A Nostalgic Dialog conversation: the Wanderer says hello and offers two choices" width="800"><p>Classic RPG-style conversations for Minecraft. Text types out letter by letter with a talking blip, characters have portraits that change with their mood, and players answer with choices that shape what happens next.</p><p>Everything is written in JSON files in a datapack or KubeJS. No coding needed.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p><a href="/wiki/nostalgicdialog/for-players">Players</a> for what a conversation looks like and how to control it.</p><p><a href="/wiki/nostalgicdialog/for-packmakers">Packmakers</a> for where the files go, and your first dialog in five minutes.</p><p>Want to see it first? Run this in game:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/dialog start @s nostalgicdialog:demo</span></span></code></pre></div><h2 id="what-you-can-build" tabindex="-1">What you can build <a class="header-anchor" href="#what-you-can-build" aria-label="Permalink to &quot;What you can build&quot;">​</a></h2><ul><li><strong>Branching conversations</strong> with as many paths as you like, and menus players can come back to</li><li><strong>Choices that are hidden</strong> until the player has earned them, or <strong>shown greyed out</strong> with a hint such as <em>(needs 3 apples)</em></li><li><strong>NPCs that remember</strong>: flags, relationship points and past conversations change what they say next time</li><li><strong>Things that happen</strong> when you talk: give or take items, run commands, raise relationship points, unlock memories from Nostalgic Memories</li><li><strong>A look of your own</strong>: portraits for every mood, a voice per character, text effects, and your own font and sounds</li></ul><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Minecraft 1.21.1 with NeoForge</li><li>Optional: <a href="/wiki/nostalgicdialog/logic/conditions#memory">Nostalgic Memories</a> for memory conditions and actions, KubeJS for keeping files in <code>kubejs/data</code>, FTB Quests or Easy NPC to start dialogs from quests and NPCs</li></ul>',13)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
